for n, q in enumerate(Q, 1):
    q = list(q)
    if n in LONGER:
        idx, text = LONGER[n]
        assert idx != q[4], (n, "patched the correct option")
        assert len(text) > len(q[3][q[4]]), (n, len(text), len(q[3][q[4]]))
        q[3] = list(q[3]); q[3][idx] = text
