assert len(Q) == 50, len(Q)
materials = []
for key, (typ, title, url, author, desc, unverified) in M.items():
    materials.append({"key": key, "type": typ, "title": title, "url": url, "author": author,
                      "description": desc + (U if unverified else "")})
questions = []
used = set()
for i, (prompt, tags, diff, opts, correct, expl, mats) in enumerate(Q, 1):
    assert len(opts) == 4 and 0 <= correct < 4, i
    for k in mats:
        assert k in M, (i, k)
        used.add(k)
    questions.append({"prompt": prompt, "tags": mapped(tags), "difficulty": diff, "options": opts,
                      "correct": correct, "explanation": expl, "materials": mats})
unused = set(M) - used
assert not unused, unused
json.dump({"name": "50 .NET interview questions", "materials": materials, "questions": questions},
          open(sys.argv[1], "w"), indent=2, ensure_ascii=False)
dist = [sum(1 for q in Q if q[4] == k) for k in range(4)]
print(f"{len(questions)} questions, {len(materials)} materials, correct-letter spread A-D: {dist}")
lens = [(len(q[3][q[4]]), sum(len(o) for j, o in enumerate(q[3]) if j != q[4]) / 3) for q in Q]
longest = sum(1 for q in Q if len(q[3][q[4]]) == max(len(o) for o in q[3]))
print(f"correct option is the longest in {longest}/50 questions")
